// Define the tagged type DateTime64
#[derive(Debug)]
enum DateTime64 {
    Nat,
    Valid(u64),
}

// Implement the isnat function
fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Create a new vector to hold the boolean results
    let mut result = Vec::with_capacity(x.len());
    
    // Iterate through each element in the input vector
    for item in x {
        match item {
            DateTime64::Nat => result.push(true),   // If it's Nat, push true
            DateTime64::Valid(_) => result.push(false), // If it's Valid, push false
        }
    }
    
    result // Return the resulting boolean vector
}

// Example usage
fn main() {
    let input = vec![DateTime64::Nat, DateTime64::Valid(123456789), DateTime64::Nat];
    let output = isnat(input);
    println!("{:?}", output); // Output: [true, false, true]
}